import ast
from pathlib import Path
import unittest


ROOT = Path(__file__).resolve().parents[1]


def source_files():
    """List project Python files without traversing dependencies or generated data."""
    files = list(ROOT.glob('*.py'))
    for directory in ('views', 'tests'):
        files.extend((ROOT / directory).glob('*.py'))
    return sorted(files)


class ProjectRulesTests(unittest.TestCase):
    """Enforce the source-citation, documentation and architecture rules in CLAUDE.md."""

    def test_headers_and_docstrings(self):
        """Require honest citations and documentation on every module, class and function."""
        for path in source_files():
            with self.subTest(file=path.name):
                text = path.read_text(encoding='utf-8')
                self.assertTrue(text.startswith(f'# {path.name}\n'))
                for marker in ('AI CITATION', 'OpenAI Codex (GPT-6)', 'Last AI change:',
                               'Based on:', 'Prompt summary:', 'Scope:', 'Reviewed by:',
                               'Changes by the team:'):
                    self.assertIn(marker, text[:1200])
                tree = ast.parse(text)
                self.assertIsNotNone(ast.get_docstring(tree))
                for node in ast.walk(tree):
                    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                        self.assertIsNotNone(ast.get_docstring(node), node.name)

    def test_import_boundaries_and_simple_python(self):
        """Keep calendar libraries and UI in their assigned modules and reject banned syntax."""
        restricted = {'requests': {'importers.py', 'calendar_import.py', 'api_client.py'},
                      'icalendar': {'calendar_import.py'},
                      'recurring_ical_events': {'calendar_import.py'},
                      'flask': {'api_server.py'}, 'numpy': {'recommender.py'},
                      'sklearn': {'recommender.py'}}
        forbidden = {'dataclasses', 'pydantic', 'sqlalchemy', 'threading', 'multiprocessing'}
        for path in source_files():
            with self.subTest(file=path.name):
                tree = ast.parse(path.read_text(encoding='utf-8'))
                for node in ast.walk(tree):
                    self.assertNotIsInstance(node, (ast.AsyncFunctionDef, ast.Await,
                                                   ast.NamedExpr, ast.Match))
                    if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp)):
                        self.assertEqual(len(node.generators), 1)
                    imports = []
                    if isinstance(node, ast.Import):
                        imports = [alias.name.split('.')[0] for alias in node.names]
                    elif isinstance(node, ast.ImportFrom):
                        imports = [(node.module or '').split('.')[0]]
                        self.assertTrue(all(alias.name != '*' for alias in node.names))
                    for module in imports:
                        self.assertNotIn(module, forbidden)
                        if module in restricted:
                            self.assertIn(path.name, restricted[module])
                        if module == 'streamlit':
                            self.assertTrue(path.parent.name == 'views' or
                                            path.name in ('app.py', 'ui_components.py'))

    def test_line_lengths_and_no_interpolated_sql(self):
        """Keep readable line lengths and reject dynamic SQL formatting at execute calls."""
        for path in source_files():
            text = path.read_text(encoding='utf-8')
            for number, line in enumerate(text.splitlines(), 1):
                self.assertLessEqual(len(line), 100, f'{path.name}:{number}')
            for node in ast.walk(ast.parse(text)):
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                    sql_calls = ('execute', 'executemany', 'executescript', 'read_sql')
                    if node.func.attr in sql_calls and node.args:
                        self.assertNotIsInstance(node.args[0], (ast.JoinedStr, ast.BinOp))
